-- Target only this global exercise; reject changed identity or conflicting manual classification.
BEGIN;
SELECT id FROM "Exercise" WHERE id='d555deb1-6eef-436d-8377-9427ac267697' AND "ownerUserId" IS NULL FOR UPDATE;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='d555deb1-6eef-436d-8377-9427ac267697' AND "ownerUserId" IS NULL AND name <> 'Crucifixo Reto com Halteres') THEN
    RAISE EXCEPTION 'Flat dumbbell fly identity changed; review manually';
  END IF;
  IF EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='d555deb1-6eef-436d-8377-9427ac267697' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL AND (SELECT count(*) FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND ((m."muscleGroup"='CHEST' AND m.role='PRIMARY') OR (m."muscleGroup"='SHOULDERS' AND m.role='SECONDARY') OR (m."muscleGroup"='BICEPS' AND m.role='SECONDARY'))) <> (SELECT count(*) FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id)) THEN
    RAISE EXCEPTION 'Flat dumbbell fly classification changed; review manually';
  END IF;
  IF EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='d555deb1-6eef-436d-8377-9427ac267697' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL AND NOT EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND m."muscleGroup"='CHEST' AND m.role='PRIMARY')) OR EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='d555deb1-6eef-436d-8377-9427ac267697' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL AND NOT EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND m."muscleGroup"='SHOULDERS' AND m.role='SECONDARY')) THEN
    RAISE EXCEPTION 'Flat dumbbell fly baseline missing; review manually';
  END IF;
END $$;
INSERT INTO "ExerciseMuscle" (id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,id,'BICEPS','SECONDARY',CURRENT_TIMESTAMP FROM "Exercise" WHERE id='d555deb1-6eef-436d-8377-9427ac267697' AND "ownerUserId" IS NULL AND "anatomyReview" IS NULL ON CONFLICT ("exerciseId","muscleGroup") DO NOTHING;
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.1","reviewedAt":"2026-10-28T00:00:00.000Z","variant":"Crucifixo bilateral com halteres em banco horizontal, cotovelos levemente flexionados e adução horizontal dos ombros.","aliases":["crucifixo reto com halteres"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020","WELSCH_2005"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020","WELSCH_2005"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020"]}],"sources":[{"id":"SAETERBAKKEN_2020","title":"Saeterbakken et al. — muscle activation in barbell bench press and dumbbell flyes (2020)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7675616/","limitation":"Dezessete homens treinados em 6RM; EMG não determina hipertrofia nem esforço individual."},{"id":"WELSCH_2005","title":"Welsch et al. — electromyographic activity during three upper-body lifts (2005)","url":"https://pubmed.ncbi.nlm.nih.gov/15903389/","limitation":"Doze participantes, EMG apenas do peitoral maior e deltoide anterior; não estabelece ênfase regional."}],"notes":"Peitoral maior como alvo; deltoide anterior e bíceps braquial como participantes secundários. A participação como estabilizador do cotovelo é inferência anatômica. Sem ênfase regional estabelecida. A lista e a amplitude são ilustrativas, não medidas de EMG nem prescrição individual.","instructions":{"description":"Adução horizontal dos braços com halteres, com foco no peitoral maior.","setup":"Deite no banco reto com pés apoiados e segure os halteres acima do peito.","execution":"Abra os braços em arco, mantendo os cotovelos levemente flexionados; retorne suavemente pelo mesmo caminho.","tips":"Mantenha o tronco apoiado e use uma amplitude confortável. A pose é ilustrativa."}}'::jsonb,"updatedAt"=CURRENT_TIMESTAMP WHERE id='d555deb1-6eef-436d-8377-9427ac267697' AND "ownerUserId" IS NULL AND "anatomyReview" IS NULL;
COMMIT;
